294	/// `onError` is declared `void` but implemented `async`, so Dart still
295	/// returns a real `Future` at runtime even though the static type hides it
296	/// — awaiting that real Future deterministically waits for the retry
297	/// delay + fetch to finish, instead of a fixed-duration sleep.
298	Future<void> _runOnError(
299	  RetryInterceptor interceptor,
300	  DioException err,
301	  ErrorInterceptorHandler handler,
302	) async {
303	  // `onError`'s declared return type is `void`, but the real implementation
304	  // is `async` and returns a real `Future` at runtime. Calling through a
305	  // `dynamic`-typed reference bypasses the static void check so that real
306	  // Future can be captured and awaited.
307	  final dynamic pending = (interceptor.onError as dynamic)(err, handler);
308	  if (pending is Future) await pending;
309	}
